from itertools import product, combinations
from collections import Counter


def _route(policy):
    exact, minimum = policy

    def solve(data):
        required = data.get('required', [])
        full = (1 << len(required)) - 1
        visit = {node: sum(1 << i for i, name in enumerate(required)
                           if name == node) for node in range(data['n'])}
        graph = [[] for _ in range(data['n'])]
        for edge in data['edges']:
            graph[edge['u']].append(edge)

        source, start = data['source'], data['start']
        initial_mask = visit[source]
        initial = (source, initial_mask, 0, start)
        best = {(source, initial_mask, 0): start}
        queue = [(start, source, initial_mask, 0)]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if best.get(state) != time:
                continue
            if (node == data['target'] and mask == full and
                    (used == data['coupons'] if exact else True)):
                return {'arrival': time}
            for edge in graph[node]:
                depart = max(time, edge['open'])
                if depart >= edge['close']:
                    continue
                choices = [(edge['duration'], used)]
                if used < data['coupons']:
                    duration = max(minimum, edge['duration'] - edge.get('discount', 0))
                    choices.append((duration, used + 1))
                for duration, next_used in choices:
                    arrival = depart + duration
                    if arrival > data['deadline']:
                        continue
                    nxt = (edge['v'], mask | visit[edge['v']], next_used)
                    if arrival < best.get(nxt, float('inf')):
                        best[nxt] = arrival
                        heapq.heappush(queue, (arrival, *nxt))
        return {'arrival': None}
    return solve


def _ledger(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}
    for position, event in enumerate(data['events']):
        sequence = event.get('sequence', 0)
        if sequence > cutoff:
            continue
        event_id = event.get('id', 'anonymous:' + str(position))
        key = (sequence, event.get('revision', 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get('opening', {}))
    half_up = data['rounding'] == 'half_up'

    def rounded(numerator):
        return (numerator + 5000) // 10000 if half_up else numerator // 10000

    for _, event in winners.values():
        if event.get('void', False):
            continue
        raw = event['price'] * event.get('quantity', 1)
        discount = min(10000, max(0, event.get('discount_bp', 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get('tax_bp', 0))
        total = net + tax
        if event.get('kind') == 'refund':
            total = -total
        key = event.get('account', 'default') + '|' + event.get('currency', 'USD')
        balances[key] = balances.get(key, 0) + total
    return {'balances': balances}


def _dependencies(data):
    packages = data['packages']
    names = sorted(packages)
    features = set(data.get('features', []))
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    options = {}
    rowmaps = {}
    for name in names:
        rows = {row['version']: row for row in packages[name]}
        rowmaps[name] = rows
        options[name] = [v for v in rows
                         if v not in blocked.get(name, []) and
                         (name not in pins or pins[name] == v)]

    best_vector = None
    best = None
    for assignment in product(*[[None] + options[name] for name in names]):
        chosen = dict(zip(names, assignment))
        valid = True
        edges = {name: [] for name in names if chosen[name] is not None}
        for name, bounds in roots.items():
            version = chosen.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        for name, version in chosen.items():
            if version is None:
                continue
            for dep in rowmaps[name][version].get('deps', []):
                feature = dep.get('feature', '')
                if feature and feature not in features:
                    continue
                target = dep['name']
                target_version = chosen.get(target)
                if (target_version is None or
                        not dep['min'] <= target_version <= dep['max']):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in edges):
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if any(version is not None and name not in reachable
               for name, version in chosen.items()):
            continue

        vector = tuple(chosen[name] if chosen[name] is not None else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = {name: version for name, version in chosen.items()
                    if version is not None}
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}


def _jobs(data):
    jobs = [job for job in data['jobs']
            if job['id'] not in data.get('blocked', [])]
    mandatory = set(data.get('mandatory', []))
    quotas = data.get('quotas', {})
    k = data['k']
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = {job['id'] for job in subset}
        if not mandatory <= ids:
            continue
        counts = Counter(job['group'] for job in subset)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job['start'], job['end']))
        ends = []
        possible = True
        for job in ordered:
            ends = [end for end in ends if end > job['start']]
            ends.append(job['end'])
            if len(ends) > 2:
                possible = False
                break
        if not possible:
            continue
        value = sum(job['value'] for job in subset)
        selected = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and selected > best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {'error': 'impossible'}
    return {'selected': list(best_ids), 'value': best_value}


